import asyncio, time

class Bucket:
    def __init__(self, per_sec):
        self.rate, self.tokens, self.t = per_sec, per_sec, time.monotonic()
    async def take(self):
        while True:
            now = time.monotonic()
            self.tokens = min(self.rate, self.tokens + (now - self.t) * self.rate)
            self.t = now
            if self.tokens >= 1:
                self.tokens -= 1
                return
            await asyncio.sleep(0.05)

async def run_claude_sync(org, client, db, norm, tomb, budget_s=300):
    bucket, t0, rep = Bucket(5.0), time.monotonic(), {'pages': 0, 'tomb': 0, '429': 0}   # 5/s = half of 600/min
    cur = db.get_cursor('claude', org)         # (updated_at, after_id) or None
    while time.monotonic() - t0 < budget_s:
        await bucket.take()
        params = {'order_by': 'updated_at'}
        if cur:
            params['after_id'] = cur.after_id
        r = await client.get(LIST_PATH, params=params)   # LIST_PATH: check current docs
        if r.status_code == 429:
            rep['429'] += 1
            await asyncio.sleep(float(r.headers.get('retry-after', 60)))
            continue
        r.raise_for_status()
        page = r.json()
        if not page['items']:
            break
        for it in page['items']:
            if it.get('deleted_at'):
                tomb(it['id'], 'vendor_tombstone'); rep['tomb'] += 1
        if norm(page['items']):                # commit only after confirm
            cur = db.commit_cursor('claude', org, page['items'][-1])
            rep['pages'] += 1
        else:
            break
    return rep

