STRIKES = 2
FREEZE = 0.05

def reconcile(db, tomb, source, rng, reported, complete, run_id):
    if not complete:
        return {'tombstoned': 0, 'struck': 0, 'frozen': False}   # no diff on a partial run
    held = db.pointers_in_range(source, rng)          # set of uris whose time is inside [from, to]
    if not held:
        return {'tombstoned': 0, 'struck': 0, 'frozen': False}
    missing = held - reported
    ratio = len(missing) / len(held)
    if ratio > FREEZE:
        # tricky part: a big loss is far more likely a broken listing than a mass delete
        db.freeze(run_id, source, ratio)
        return {'tombstoned': 0, 'struck': 0, 'frozen': True}
    db.clear_strikes(source, held & reported)
    tombstoned = struck = 0
    for uri in missing:
        n = db.add_strike(source, uri, run_id)
        if n >= STRIKES:
            tomb(uri, 'window_missing')
            db.drop_strike(source, uri)
            tombstoned += 1
        else:
            struck += 1
    return {'tombstoned': tombstoned, 'struck': struck, 'frozen': False}

