def chunk_thread(msgs, gap=1800, cap=40):
    groups, cur = [], []
    for m in sorted(msgs, key=lambda m: m.ts):
        new = cur and ((m.thread_id and m.thread_id != cur[-1].thread_id) or (not m.thread_id and m.ts - cur[-1].ts > gap))
        if new:
            groups.append(cur); cur = []
        cur.append(m)
    if cur: groups.append(cur)
    return [to_chunk(g[i:i+cap]) for g in groups for i in range(0, len(g), cap)]
